const accounts = $('Get Ad Accounts').first().json.data || [];

let metaToken = null;
try {
  const metaResp = $('Get Meta Credentials').first().json;
  metaToken = metaResp && metaResp.credentials ? metaResp.credentials.access_token : null;
} catch (e) { metaToken = null; }

let google = null;
try {
  const googleResp = $('Get Google Credentials').first().json;
  google = googleResp && googleResp.credentials ? googleResp.credentials : null;
} catch (e) { google = null; }

return accounts.map(account => ({
  json: {
    ...account,
    app_url: $('Config').first().json.app_url,
    meta_access_token: metaToken,
    google_credentials: google,
  }
}));

const account = $('Merge Config + Accounts').item.json;
const resp = $('Meta - Get Campaigns').first().json;
const campaigns = (resp.data || []).map(c => ({
  external_id: c.id,
  name: c.name,
  status: (c.status || 'ACTIVE').toLowerCase(),
  objective: c.objective || null,
  start_date: c.start_time ? c.start_time.substring(0, 10) : null,
  end_date: c.stop_time ? c.stop_time.substring(0, 10) : null,
  raw_data: c,
}));

return [{
  json: {
    client_ad_account_id: account.id,
    platform: 'meta',
    campaigns,
  }
}];

const account = $('Merge Config + Accounts').item.json;
const resp = $('Meta - Get Insights (D-1)').first().json;
const yesterday = $today.minus({ days: 1 }).toFormat('yyyy-MM-dd');

function sumActions(list, types) {
  if (!list) return 0;
  return list.filter(a => types.includes(a.action_type)).reduce((sum, a) => sum + parseFloat(a.value || 0), 0);
}

const snapshots = (resp.data || []).map(row => ({
  entity_level: 'campaign',
  entity_id: row.campaign_id,
  entity_name: row.campaign_name,
  spend: parseFloat(row.spend || 0),
  revenue: sumActions(row.action_values, ['purchase', 'omni_purchase']),
  impressions: parseInt(row.impressions || 0, 10),
  clicks: parseInt(row.clicks || 0, 10),
  conversions: Math.round(sumActions(row.actions, ['purchase', 'omni_purchase', 'lead', 'offsite_conversion.fb_pixel_purchase'])),
  reach: parseInt(row.reach || 0, 10),
  raw_data: row,
}));

return [{
  json: {
    client_ad_account_id: account.id,
    platform: 'meta',
    snapshot_date: yesterday,
    snapshots,
  }
}];

const account = $('Merge Config + Accounts').item.json;
const resp = $input.first().json;
const results = resp.results || [];

const campaigns = results.map(r => ({
  external_id: String(r.campaign.id),
  name: r.campaign.name,
  status: (r.campaign.status || 'ENABLED').toLowerCase(),
  objective: r.campaign.advertisingChannelType || null,
  start_date: r.campaign.startDate || null,
  end_date: r.campaign.endDate || null,
  raw_data: r.campaign,
}));

return [{
  json: {
    client_ad_account_id: account.id,
    platform: 'google',
    campaigns,
  }
}];

const account = $('Merge Config + Accounts').item.json;
const resp = $('Google - Search (Campaigns + Metrics D-1)').first().json;
const results = resp.results || [];
const yesterday = $today.minus({ days: 1 }).toFormat('yyyy-MM-dd');

const snapshots = results.map(r => ({
  entity_level: 'campaign',
  entity_id: String(r.campaign.id),
  entity_name: r.campaign.name,
  spend: parseInt(r.metrics.costMicros || 0, 10) / 1000000,
  revenue: parseFloat(r.metrics.conversionsValue || 0),
  impressions: parseInt(r.metrics.impressions || 0, 10),
  clicks: parseInt(r.metrics.clicks || 0, 10),
  conversions: Math.round(parseFloat(r.metrics.conversions || 0)),
  reach: 0,
  raw_data: r.metrics,
}));

return [{
  json: {
    client_ad_account_id: account.id,
    platform: 'google',
    snapshot_date: yesterday,
    snapshots,
  }
}];
